{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C54"],
      "claim": "Verapamil, the highest-transfer analogue (0.9056), has an absolute oral bioavailability of 22.0% in normal subjects, above the 20% threshold, and shares dimethoxyphenyl and tertiary-amine features with the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Noscapine, a high-transfer analogue (0.8317) with multiple methoxy groups and a rigid polycyclic amine scaffold, shows an absolute oral bioavailability of 30% in healthy volunteers.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Sulpiride, despite its polar sulfonamide and incomplete absorption, has a reported bioavailability of 30%, supporting F ≥ 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Encainide, a high-transfer analogue (0.8135), shows an absolute oral bioavailability of 32 ± 7% in normal subjects, supporting a high prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Alfentanil, with a transfer score of 0.803, has an oral bioavailability of 0.45 ± 0.09 (45%) in control subjects, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C60"],
      "claim": "Levosulpiride, a close analogue of sulpiride with a transfer score of 0.8002, has an absolute oral bioavailability of 23.4% in Chinese volunteers, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Valbenazine, a high-transfer analogue (0.8001) containing a dimethoxytetrahydroisoquinoline-like core, has an absolute oral bioavailability of approximately 49% in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Colchicine, with a transfer score of 0.7884, has a mean absolute oral bioavailability of 55% (range 24–88%) in elderly subjects, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Codeine, a high-transfer analogue (0.7876), has an oral bioavailability of 42–71% in healthy volunteers, clearly above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All high-transfer experimental analogues show mean absolute oral bioavailability at or above 20%, mostly in the 22–55% range, supporting a high F ≥ 20% prediction for the query. No affirmative low-bioavailability evidence transfers to the query.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the query molecule; the prediction relies on structural and pharmacological analogues.",
    "Several analogue values are near the 20% threshold with wide interindividual variability, so the exact F for the query could be borderline.",
    "No query-specific data on first-pass metabolism, efflux transport, or solubility are available."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

